class ElektrikliAraba(Araba):
    def __init__(self, marka, model, yil, batarya_kwh):
        super().__init__(marka, model, yil)
        self.batarya_kwh = batarya_kwh

    def sarj_suresi(self) -> float:
        return self.batarya_kwh / 11  # 11kW şarj hızı

tesla = ElektrikliAraba('Tesla', 'Model 3', 2024, 75)
print(tesla.sarj_suresi())  # 6.8 saat
